<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {t} from '../i18n'
import {LABELS,type AgentKind,type Group,type Run,type Stage} from '../../shared/types'
import {stages,modeName} from '../content'
import Icon from './Icon.vue'
import {agentStatus,latestAttempt,activityStatus} from '../agent-status'
const props=defineProps<{group:Group;run?:Run;responding:string[]}>()
defineEmits<{inspect:[kind:AgentKind]}>()
const clock=ref(Date.now()),collapsed=ref(true)
let timer:ReturnType<typeof setInterval>
onMounted(()=>timer=setInterval(()=>clock.value=Date.now(),1000));onUnmounted(()=>clearInterval(timer))
const members=computed(()=>props.run?.participants||props.group.agents)
const removed=computed(()=>props.run?.excludedAgents||[])
const height=computed(()=>Math.max(156,Math.ceil(members.value.length/2)*94+24))
const steps=computed<Stage[]>(()=>(props.run?.mode||props.group.mode)==='parallel'?((props.run?.settings.executeAfter??props.group.executeAfter)?['preparing','discussing','producing','checking','finished']:['preparing','discussing','summarizing','finished']):props.run?.delivery==='text'?['preparing','discussing','checking','finished']:props.run?.mode==='review'||(!props.run&&props.group.mode==='review')?['preparing','producing','checking','finished']:(props.run?.settings.executeAfter??props.group.executeAfter)?['preparing','discussing','producing','checking','finished']:['preparing','discussing','summarizing','finished'])
const phase=computed(()=>props.run?.stage==='finished'&&props.run.status!=='completed'?props.run.lastStage:props.run?.stage||'preparing')
const position=computed(()=>phase.value?steps.value.indexOf(phase.value):-1)
const current=computed(()=>props.run?.mode==='review'&&props.run.delivery==='text'&&phase.value==='discussing'?t('回答问题'):phase.value==='producing'&&(props.run?.mode||props.group.mode)!=='review'?t('汇总与制作'):phase.value?stages[phase.value]:t('阶段记录不可用'))
function latest(kind:AgentKind){return latestAttempt(props.run,kind)}
function isActive(kind:AgentKind){return props.run?.status==='running'&&!removed.value.some(a=>a.kind===kind)&&props.run.activeAgents?.includes(kind)}
function state(kind:AgentKind){return t(agentStatus(props.run,kind))}
function elapsed(kind:AgentKind){const a=latest(kind);return a?Math.max(0,Math.floor(((a.finishedAt?Date.parse(a.finishedAt):clock.value)-Date.parse(a.startedAt))/1000)):0}
function path(i:number){const y=16+Math.floor(i/2)*94+41,mid=height.value/2;return i%2===0?`M 470 ${mid} C 385 ${mid}, 355 ${y}, 270 ${y}`:`M 530 ${mid} C 615 ${mid}, 645 ${y}, 730 ${y}`}
</script>
<template><section class="run-progress collaboration-map" :aria-label="t('协作进度')"><header class="map-heading"><strong>{{ modeName(run?.mode||group.mode) }}</strong><span>{{ t('点击成员，查看每一轮执行记录') }}</span><button class="text-button" @click="collapsed=!collapsed">{{ collapsed?t('展开流程图'):t('收起流程图') }}<Icon :name="collapsed?'down':'chevron'" :size="13"/></button></header><div class="team-graph" :class="{compact:collapsed}" :style="collapsed?{}:{height:height+'px'}"><svg v-if="!collapsed" class="graph-lines" :viewBox="`0 0 1000 ${height}`" preserveAspectRatio="none" aria-hidden="true"><path v-for="(kind,i) in members" :key="kind" :d="path(i)" :class="{active:isActive(kind),broken:removed.some(a=>a.kind===kind)}"/></svg><div v-if="!collapsed" class="graph-hub"><span :class="['hub-icon',{running:run?.activeAgents?.length}]"><Icon name="orbit" :size="25"/></span><strong>{{ current }}</strong><small>{{ run?.activeAgents?.length?t('团队正在推进'):run?.stage==='finished'?t('本次运行已结束'):t('等待开始') }}</small></div><button v-for="(kind,i) in members" :key="kind" type="button" :class="['diagram-agent','roster-agent',{working:isActive(kind),removed:removed.some(a=>a.kind===kind)}]" :style="collapsed?{}:{top:(16+Math.floor(i/2)*94)+'px',[i%2?'right':'left']:'0'}" :title="removed.find(a=>a.kind===kind)?.reason||state(kind)" @click="$emit('inspect',kind)"><span class="avatar" :data-agent="kind">{{ LABELS[kind].slice(0,1) }}</span><span class="diagram-agent-copy"><strong>{{ LABELS[kind] }}</strong><small>{{ state(kind) }}<span v-if="isActive(kind)" class="activity-detail"> · {{ t(activityStatus(latest(kind))) }}</span></small><span class="agent-metrics" v-if="latest(kind)">{{ (run?.mode||group.mode)==='parallel'?t('单轮分析'):t('第 {round} 轮',{round:latest(kind)!.round}) }} · {{ elapsed(kind) }}s</span></span><Icon v-if="removed.some(a=>a.kind===kind)" name="alert" :size="16"/><span v-else-if="isActive(kind)" class="pulse-dot"/><Icon v-else name="chevron" :size="14"/></button></div><ol v-if="!collapsed" class="phase-track" :class="{'single-pass':(run?.mode||group.mode)==='parallel'||(run?.settings.executeAfter??group.executeAfter)}"><li v-for="(step,i) in steps" :key="step" :data-stage="step" :class="{done:run?.status==='completed'||i<position,current:i===position&&run?.status!=='completed',attention:run&&['partial','failed','cancelled','interrupted'].includes(run.status)&&i===position}"><span class="phase-node"><Icon v-if="run?.status==='completed'||i<position" name="check" :size="13"/><span v-else>{{ i+1 }}</span></span><span>{{ step==='discussing'&&run?.mode==='review'&&run.delivery==='text'?t('回答问题'):step==='producing'&&(run?.mode||group.mode)!=='review'?t('汇总与制作'):stages[step] }}</span></li></ol><div v-if="removed.length" class="degraded-banner" role="alert"><Icon name="alert" :size="17"/><div><strong>{{ t('团队已缩减，本次不代表原团队全员认可。') }}</strong><p v-for="item in removed" :key="item.kind">{{ LABELS[item.kind] }} · {{ t(item.reason) }}</p></div></div></section></template>
<style scoped>
.collaboration-map{padding-top:12px;padding-bottom:14px;background:var(--color-f9fbf6,#f9fbf6)}.map-heading{display:flex;gap:13px;align-items:center;font-size:12px;color:var(--color-536957,#536957)}.map-heading>strong{font-size:13px}.map-heading>span{color:var(--color-87977e,#87977e);font-size:11px}.map-heading>.text-button{margin-left:auto;font-size:11px}.team-graph{position:relative;margin-top:5px}.graph-lines{position:absolute;width:100%;height:100%;inset:0;pointer-events:none}.graph-lines path{fill:none;stroke:var(--color-c6d7bd,#c6d7bd);stroke-width:1.7;vector-effect:non-scaling-stroke}.graph-lines path.active{stroke:var(--color-42866b,#42866b);stroke-width:2.3;stroke-dasharray:7 5;animation:collaboration-flow 1.1s linear infinite}.graph-lines path.broken{stroke:var(--color-d1b0a0,#d1b0a0);stroke-dasharray:3 5}.graph-hub{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:180px;display:flex;flex-direction:column;align-items:center;gap:7px;text-align:center;background:var(--color-f9fbf6,#f9fbf6);padding:7px 14px;z-index:1}.hub-icon{display:flex;padding:9px;background:var(--color-e5eedf,#e5eedf);border-radius:14px;color:var(--color-568257,#568257)}.hub-icon.running{box-shadow:0 0 0 6px var(--color-e4efdd80,#e4efdd80)}.graph-hub>strong{font-size:14px;font-weight:600}.graph-hub>small{font-size:11px;color:var(--color-819173,#819173)}.diagram-agent{position:absolute;width:27%;height:82px;min-width:0;gap:9px;text-align:left;padding:9px 12px;cursor:pointer;background:var(--color-fffefb,#fffefb);box-shadow:0 2px 5px var(--color-28422b04,#28422b04);z-index:2}.diagram-agent:hover{border-color:var(--color-699c77,#699c77);background:var(--color-f0f6e8,#f0f6e8);box-shadow:0 3px 12px var(--color-28422b0b,#28422b0b)}.diagram-agent.working{border-color:var(--color-6d9e78,#6d9e78)}.diagram-agent.removed{background:var(--color-fbf1eb,#fbf1eb);border-color:var(--color-d7b6a5,#d7b6a5);color:var(--color-9f614d,#9f614d)}.diagram-agent-copy{flex:1;min-width:0}.diagram-agent-copy strong{font-size:13px}.diagram-agent-copy small{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:11px}.agent-metrics{font-size:10px;color:var(--color-91a083,#91a083);display:block;margin-top:3px}.diagram-agent>svg,.diagram-agent>.pulse-dot{flex-shrink:0}.compact{display:flex;flex-wrap:wrap;gap:9px;margin:12px 0}.compact .diagram-agent{position:static;width:auto;min-width:180px;flex:1}.phase-track{margin-top:6px}.degraded-banner{display:flex;align-items:flex-start;gap:9px;margin-top:14px;background:var(--color-fbefe5,#fbefe5);border:1px solid var(--color-e4ccb5,#e4ccb5);color:var(--color-956343,#956343);padding:12px 14px;border-radius:8px;font-size:12px;line-height:1.8}.degraded-banner>svg{margin-top:3px;flex-shrink:0}.degraded-banner p{font-size:11px;margin-top:3px;overflow-wrap:anywhere}@keyframes collaboration-flow{to{stroke-dashoffset:-24}}@media(max-width:1150px){.diagram-agent{padding:8px;gap:6px;width:29%}.diagram-agent>.avatar{width:25px;height:25px;min-width:25px}.graph-hub{width:140px;padding:5px}.diagram-agent-copy strong{font-size:11px}.agent-metrics{font-size:9px}.graph-hub>strong{font-size:12px}.map-heading>span{display:none}}
</style>

<style scoped>
.phase-track{display:flex!important;align-items:center!important;gap:0!important;width:100%;padding:12px 0 4px!important;overflow-x:auto}.phase-track li{display:flex!important;align-items:center!important;flex:1 0 auto!important;gap:7px!important;position:relative;white-space:nowrap;min-width:0}.phase-track li::after{content:"→"!important;position:static!important;background:none!important;height:auto!important;width:auto!important;flex:1!important;text-align:center;color:var(--color-afbea5,#afbea5);margin:0 12px}.phase-track li:last-child{flex:0 0 auto!important}.phase-track li:last-child::after{display:none!important}.phase-track li[data-stage="discussing"]::after{content:"⇄"!important;color:var(--color-728e69,#728e69);font-size:19px}.phase-track li>span:last-child{font-size:12px;white-space:nowrap}.phase-node{flex-shrink:0}
</style>

<style scoped>.phase-track.single-pass li[data-stage="discussing"]::after{content:"→"!important}</style>

<style scoped>
.collaboration-map{padding-top:6px!important;padding-bottom:6px!important}.map-heading{margin-bottom:0}.compact{margin:6px 0 0;gap:8px}.compact .diagram-agent{height:46px!important;padding:5px 10px;box-shadow:none}.compact .avatar{width:28px;height:28px;min-width:28px}.diagram-agent-copy small{margin-top:1px}.activity-detail{font-weight:400}.compact .activity-detail{display:none}
</style>
